driverScript:
module.exports = {
  password: '',
  authPrefix: '',
  isAuthenticated: false,
  onConnect: function(transport, config) {
    this.password = config.password || '';
    this.authPrefix = '';
    this.isAuthenticated = false;
    console.log('PJLink Projector Driver Connecting...');
    engine.setStatus('connecting');
  },
  onMessage: function(transport, text, bytes) {
    var msg = (text || '').trim();
    console.log('PJLink RX: ' + msg);
    if (msg.indexOf('PJLINK 0') === 0) {
      this.isAuthenticated = true;
      this.authPrefix = '';
      engine.setStatus('connected');
      transport.send('%1POWR ?\r');
      transport.send('%1INPT ?\r');
      transport.send('%1LAMP ?\r');
      return;
    }
    if (msg.indexOf('PJLINK 1 ') === 0) {
      var randomKey = msg.substring(9).trim();
      var digest = engine.crypto.md5(randomKey + this.password);
      this.authPrefix = digest;
      this.isAuthenticated = true;
      engine.setStatus('connected');
      transport.send(this.authPrefix + '%1POWR ?\r');
      transport.send(this.authPrefix + '%1INPT ?\r');
      transport.send(this.authPrefix + '%1LAMP ?\r');
      return;
    }
    if (msg.indexOf('%1POWR=') !== -1) {
      var pstate = msg.split('=')[1];
      var ptext = pstate === '1' ? 'ON' : (pstate === '0' ? 'STANDBY' : (pstate === '2' ? 'COOLING' : 'WARMING'));
      engine.setVariable('projector_power', ptext);
    }
    if (msg.indexOf('%1INPT=') !== -1) {
      var istate = msg.split('=')[1];
      engine.setVariable('current_input', istate);
    }
    if (msg.indexOf('%1LAMP=') !== -1) {
      var lparts = msg.split('=')[1].split(' ');
      if (lparts.length >= 1) engine.setVariable('lamp_hours', lparts[0]);
      if (lparts.length >= 2) engine.setVariable('lamp_status', lparts[1] === '1' ? 'ON' : 'OFF');
    }
  },
  onAction: function(transport, actionId, params) {
    var prefix = this.authPrefix || '';
    if (actionId === 'power') {
      var state = params.state === '0' || params.state === 'off' || params.state === 'standby' ? '0' : '1';
      transport.send(prefix + '%1POWR ' + state + '\r');
      return 'PJLink: Power ' + (state === '1' ? 'ON' : 'OFF');
    }
    if (actionId === 'input_switch') {
      var inputCode = params.input_source || '31';
      transport.send(prefix + '%1INPT ' + inputCode + '\r');
      return 'PJLink: Switch Input to ' + inputCode;
    }
    if (actionId === 'mute') {
      var muteCode = params.mute_mode || '30';
      transport.send(prefix + '%1AVMT ' + muteCode + '\r');
      return 'PJLink: A/V Mute ' + muteCode;
    }
    if (actionId === 'query_status') {
      transport.send(prefix + '%1POWR ?\r');
      transport.send(prefix + '%1INPT ?\r');
      transport.send(prefix + '%1LAMP ?\r');
      return 'PJLink: Queried Status';
    }
    return 'PJLink: Unknown action ' + actionId;
  },
  onDisconnect: function() {
    engine.setStatus('disconnected');
  }
};
